export default "import { ChangeDetectionStrategy, Component, Input } from '@angular/core';\n\n@Component({\n  standalone: false,\n  selector: 'documentation-widget-demo',\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  templateUrl: './demo.component.html',\n  styleUrls: ['./demo.component.scss'],\n})\nexport class DocumentationWidgetDemoComponent {\n  @Input() demoTitle: string;\n  @Input() component: string;\n  @Input() id: string;\n  @Input() code: string;\n  @Input() markup: string;\n  @Input() module: string;\n  @Input() readme: string;\n  @Input() path: string;\n  @Input() files: { name: string; source: string }[];\n  @Input() showCode = false;\n  viewMode = 'code';\n  tabs: any[] = [\n    { name: 'Source Code', type: 'code' },\n    { name: 'Template Markup', type: 'markUp' },\n    { name: 'Module', type: 'module' },\n  ];\n\n  activeTab = 'code';\n\n  getGithubLink() {\n    const baseRepoURL = 'https://github.com/GSA/ngx-uswds/tree/main/';\n    if (this.path) {\n      return baseRepoURL + this.path;\n    }\n    return false;\n  }\n\n  tabType(name: string) {\n    const ext = name.split('.').pop();\n    return (\n      {\n        html: 'HTML',\n        scss: 'Style (SCSS)',\n        css: 'Style (CSS)',\n        ts: 'Typescript',\n      }[ext] || 'Code'\n    );\n  }\n}\n";